DO $migrate$
DECLARE
  d uuid; r record; v_t text; v_n bigint;
  v_led_before jsonb; v_led_after jsonb; v_rows text; v_others text; v_fn_n bigint; v_ver bigint; v_readers text[];
BEGIN
  -- ---------------------------------------------------------------- 0. preflight
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'training_sessions' AND column_name IN ('actual_start', 'actual_end', 'setup_min'))
     OR EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.training_sessions'::regclass AND conname IN ('training_sessions_actual_pair', 'training_sessions_actual_whole_minutes', 'training_sessions_actual_length', 'training_sessions_setup_range'))
     OR to_regprocedure('public.finalize_training_session(uuid, time without time zone, time without time zone, integer)') IS NOT NULL THEN
    RAISE EXCEPTION 'PREFLIGHT: actual_start / actual_end / setup_min, a slice-T constraint, or the times finalize already exists — Slice T looks applied. Refusing.';
  END IF;
  FOR r IN SELECT * FROM (VALUES
      ('finalize_training_session(p_session_id uuid, p_duration_min integer)', '3f31142bae70c8fd2001c4fb657f4efa'),
      ('correct_training_session(p_session_id uuid, p_changes jsonb, p_add uuid[], p_remove uuid[], p_reason text)', 'ec6b3c29d4cf472527ec84f948b84b88'),
      ('tg_training_session_lock_guard()', '47918d20ab527240e54360eacca00cac'),
      ('attested_training(p_dept uuid, p_from timestamp with time zone, p_to timestamp with time zone)', 'aff25333771cd38c1f473bcde5e1e96e'),
      ('dept_iso_hours_for(p_dept uuid, p_from timestamp with time zone, p_to timestamp with time zone)', '705c9a9b5532d28824f5e50e74d6059f'),
      ('open_signin(p_session_id uuid)', '36aca8f0835d8b6444d51ad1cc791b17'),
      ('drill_window_presence(p_session_id uuid)', 'b6161a6b7e366048fb1afce2d0993401'),
      ('reopen_training_session(p_session_id uuid, p_reason text)', '278865924ec3336a8ab36a1e4b81fe9b'),
      ('my_department_id()', '87f546659c3804a943b48e419e017f18'),
      ('my_member_id()', '3f66369c8af7bc07ec59831af6536fee'),
      ('is_training_manager()', '472b87b0abca586ba0a13cd615b376fe'),
      ('recompute_training_plan_last_iso(p_plan_id uuid)', 'f8da6df3d9e1366b618a11d96b4980f1')) v(sig, md5) LOOP
    SELECT md5(pg_get_functiondef(p.oid)) INTO v_t FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND (p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')') = r.sig;
    IF v_t IS DISTINCT FROM r.md5 THEN RAISE EXCEPTION 'PREFLIGHT: % drifted from the capture (or is gone). Refusing.', r.sig; END IF;
  END LOOP;
  IF (SELECT md5(string_agg(t.tgname || '|' || pg_get_triggerdef(t.oid), ',' ORDER BY t.tgname COLLATE "C")) FROM pg_trigger t WHERE t.tgrelid = 'public.training_sessions'::regclass AND NOT t.tgisinternal) IS DISTINCT FROM 'de3d15eea057428cd6ece6612e7e8775' THEN
    RAISE EXCEPTION 'PREFLIGHT: a training_sessions trigger changed. Refusing.';
  END IF;
  IF (SELECT md5(string_agg(conname || '|' || pg_get_constraintdef(oid), ',' ORDER BY conname COLLATE "C")) FROM pg_constraint WHERE conrelid = 'public.training_sessions'::regclass AND contype <> 'n' AND conname NOT LIKE 'training_sessions\_actual\_%' AND conname <> 'training_sessions_setup_range') IS DISTINCT FROM '56d93bbf68ed673369ecc7f1f9b0f981' THEN RAISE EXCEPTION 'PREFLIGHT: a training_sessions constraint changed. Refusing.'; END IF;
  IF (SELECT md5(string_agg(tablename || '|' || policyname || '|' || cmd || '|' || roles::text || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''), ',' ORDER BY tablename, policyname)) FROM pg_policies WHERE schemaname = 'public') IS DISTINCT FROM 'a9947383b4635e2e54fa89fa81947fc9' THEN RAISE EXCEPTION 'PREFLIGHT: a public policy changed since the capture. Refusing.'; END IF;
  IF (SELECT string_agg(column_name || ':' || udt_name || ':' || is_nullable, ',' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'training_sessions') IS DISTINCT FROM 'id:uuid:NO,department_id:uuid:NO,plan_id:uuid:YES,title:text:NO,date:date:NO,done:bool:NO,created_at:timestamptz:NO,signin_token:text:YES,signin_open:bool:NO,series_id:uuid:YES,audience:text:NO,start_time:time:YES,counts_toward_attendance:bool:NO,location_lat:float8:YES,location_lng:float8:YES,location_radius_m:int4:YES,location_label:text:YES,is_offsite:bool:NO,duration_min:int2:YES,is_meeting:bool:NO,status:text:NO' THEN RAISE EXCEPTION 'PREFLIGHT: the training_sessions columns changed since the capture. Refusing.'; END IF;
  SELECT count(*) INTO v_fn_n FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f';
  SELECT count(*) INTO v_ver FROM public.station_presence WHERE verified;
  v_rows := (SELECT md5(coalesce(string_agg((to_jsonb(ts) - 'actual_start' - 'actual_end' - 'setup_min')::text, ',' ORDER BY ts.id), '')) FROM public.training_sessions ts);
  v_others := (SELECT md5(string_agg(md5(pg_get_functiondef(p.oid)) || coalesce(p.proacl::text, ''), ',' ORDER BY p.oid::regprocedure::text)) FROM pg_proc p
       WHERE p.pronamespace = 'public'::regnamespace AND p.prokind = 'f' AND p.oid::regprocedure::text NOT IN ('correct_training_session(uuid,jsonb,uuid[],uuid[],text)', 'tg_training_session_lock_guard()', 'finalize_training_session(uuid,time without time zone,time without time zone,integer)'));
  v_readers := (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text), '{}') FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prosrc ~ '(actual_start|actual_end|setup_min)');

    v_led_before := '{}'::jsonb;
    FOR d IN SELECT id FROM public.departments ORDER BY id LOOP
      v_led_before := v_led_before || jsonb_build_object(d::text, jsonb_build_object(
        'attested', (SELECT md5(coalesce(string_agg(a.member_id || '|' || a.session_id || '|' || a.start_at || '|' || a.end_at || '|' || a.optional, ',' ORDER BY a.member_id, a.session_id), ''))
                       FROM public.attested_training(d, '1900-01-01'::timestamptz, '2200-01-01'::timestamptz) a),
        'iso', (SELECT md5(coalesce(string_agg(h.member_id || '|' || h.training_hours || '|' || h.standby_hours || '|' || h.iso_total_hours, ',' ORDER BY h.member_id), ''))
                  FROM public.dept_iso_hours_for(d, '1900-01-01'::timestamptz, '2200-01-01'::timestamptz) h)));
    END LOOP;

  -- ---------------------------------------------------------------- 1. columns + CHECKs
  ALTER TABLE public.training_sessions ADD COLUMN actual_start time, ADD COLUMN actual_end time, ADD COLUMN setup_min smallint;
  ALTER TABLE public.training_sessions ADD CONSTRAINT training_sessions_actual_pair CHECK ((actual_start IS NULL) = (actual_end IS NULL));
  ALTER TABLE public.training_sessions ADD CONSTRAINT training_sessions_actual_whole_minutes CHECK (actual_start IS NULL OR (extract(second from actual_start) = 0 AND extract(second from actual_end) = 0 AND actual_end <> actual_start));
  ALTER TABLE public.training_sessions ADD CONSTRAINT training_sessions_actual_length CHECK (actual_start IS NULL OR duration_min IS NOT DISTINCT FROM ((extract(epoch from (actual_end - actual_start)) / 60)::integer + case when actual_end <= actual_start then 1440 else 0 end));
  ALTER TABLE public.training_sessions ADD CONSTRAINT training_sessions_setup_range CHECK (setup_min IS NULL OR setup_min BETWEEN 0 AND 600);

  -- ---------------------------------------------------------------- 2. the lock guard (the three new columns: set once at Finalize, Correct-only after)
CREATE OR REPLACE FUNCTION public.tg_training_session_lock_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 C7 — once a session is FINALIZED or HAS ATTENDANCE (Slice 7: or is CANCELLED), the fields that define the
    -- record (and the attested hours derived from it) change only through the RPCs, which set the transaction-local flag.
    -- Exempt so Finalize / sign-in keep working: done, signin_open, signin_token, location_lat/lng/radius_m,
    -- location_label, and duration_min NULL -> a value on a not-yet-finalized row (Finalize's length prompt).
    -- Slice 7: status ('scheduled'/'cancelled') changes ONLY under the flag (approve_session_change), on any row, and a new
    -- row is always 'scheduled'. date / start_time stay free on an upcoming, unattended session (plain Edit — ruling 3b).
    -- Applies to EVERY writer, the table owner included — a hand fix in the SQL editor must set the flag on purpose.
    -- B4C:E1E3 slice T — actual_start / actual_end / setup_min follow duration_min's rule: set once on a not-yet-finalized row
    -- (Finalize), Correct-only after.
    begin
      if coalesce(current_setting('b4c.session_correction', true), '') = 'on' then return NEW; end if;
      if TG_OP = 'INSERT' then
        if NEW.status is distinct from 'scheduled' then
          raise exception 'STATUS_LOCKED: a session is created scheduled — cancelling takes the two-person sign-off.' using errcode = '42501';
        end if;
        return NEW;
      end if;
      if NEW.status is distinct from OLD.status then
        raise exception 'STATUS_LOCKED: a session is cancelled or restored only through the two-person sign-off.' using errcode = '42501';
      end if;
      if not (OLD.done is true or OLD.status = 'cancelled' or exists (select 1 from public.session_attendance sa where sa.session_id = OLD.id)) then
        return NEW;
      end if;
      if NEW.title is distinct from OLD.title
         or NEW."date" is distinct from OLD."date"
         or NEW.start_time is distinct from OLD.start_time
         or NEW.audience is distinct from OLD.audience
         or NEW.plan_id is distinct from OLD.plan_id
         or NEW.counts_toward_attendance is distinct from OLD.counts_toward_attendance
         or NEW.is_meeting is distinct from OLD.is_meeting
         or NEW.is_offsite is distinct from OLD.is_offsite
         or NEW.department_id is distinct from OLD.department_id
         or NEW.series_id is distinct from OLD.series_id
         or (NEW.duration_min is distinct from OLD.duration_min
             and not (OLD.duration_min is null and OLD.done is not true))
         or (NEW.actual_start is distinct from OLD.actual_start
             and not (OLD.actual_start is null and OLD.done is not true))
         or (NEW.actual_end is distinct from OLD.actual_end
             and not (OLD.actual_end is null and OLD.done is not true))
         or (NEW.setup_min is distinct from OLD.setup_min
             and not (OLD.setup_min is null and OLD.done is not true)) then
        raise exception 'LOCKED_SESSION: this session is finalized, cancelled or has attendance — change it with Correct (or Restore), which is logged.'
          using errcode = '42501';
      end if;
      return NEW;
    end;
    $function$
;

  -- ---------------------------------------------------------------- 3. correct_training_session (times correctable; length recomputed; disagreeing length refused)
CREATE OR REPLACE FUNCTION public.correct_training_session(p_session_id uuid, p_changes jsonb, p_add uuid[], p_remove uuid[], p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:slice6 — the gated, logged correction of a LOCKED session (finalized, sign-in open, or anyone on the roll).
    -- C1 hybrid: a training manager within 14 days of the drill (Central); older = Department Admin only (D1: the ROLE,
    -- never Project Admin). C2: a reason of 10+ characters. Fields: §2a whitelist only. Roster: add/remove in the same
    -- transaction; the membership-window triggers still run, and a refusal there aborts the whole call (nothing written).
    -- B4C:E1E3 slice T — actual_start / actual_end / setup_min are correctable. With times present the length is DERIVED from
    -- them (the CHECK enforces it); a duration_min that disagrees is refused. Clearing both times leaves a length-only session.
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_today  date := (now() at time zone 'America/Chicago')::date;
      v_reason text := btrim(coalesce(p_reason, ''));
      v_chg    jsonb := coalesce(p_changes, '{}'::jsonb);
      v_keys   constant text[] := array['title', 'date', 'start_time', 'duration_min', 'audience', 'plan_id',
                                        'counts_toward_attendance', 'is_meeting', 'is_offsite', 'location_label',
                                        'actual_start', 'actual_end', 'setup_min'];
      s        public.training_sessions%rowtype;
      v_bad    text[];
      n_title text; n_date date; n_start time; n_dur integer; n_aud text; n_plan uuid;
      n_counts boolean; n_meet boolean; n_off boolean; n_label text;
      n_astart time; n_aend time; n_setup integer; v_span integer;
      v_diff   jsonb := '{}'::jsonb;
      v_add    uuid[]; v_rem uuid[];
      v_before integer; v_after integer;
      v_audit  uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can correct a session.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      -- B4C:slice7 — a cancelled session is restored (two-person), not corrected.
      if s.status = 'cancelled' then raise exception 'CANCELLED: this session was cancelled — restore it before correcting it.'; end if;
      if not (s.done or s.signin_open or exists (select 1 from public.session_attendance sa where sa.session_id = s.id)) then
        raise exception 'NOT_LOCKED: this session can still be edited normally — no correction needed.';
      end if;
      if length(v_reason) < 10 then raise exception 'REASON_REQUIRED: say why (at least 10 characters).'; end if;
      if jsonb_typeof(v_chg) <> 'object' then raise exception 'BAD_CHANGES: changes must be a JSON object.'; end if;
      select array_agg(k order by k) into v_bad from jsonb_object_keys(v_chg) k where k <> all (v_keys);
      if v_bad is not null then raise exception 'UNKNOWN_FIELD: % cannot be corrected here.', array_to_string(v_bad, ', '); end if;

      -- the corrected values (an absent key = unchanged)
      n_title  := case when v_chg ? 'title'        then btrim(v_chg->>'title') else s.title end;
      n_date   := case when v_chg ? 'date'         then (v_chg->>'date')::date else s."date" end;
      n_start  := case when v_chg ? 'start_time'   then nullif(v_chg->>'start_time', '')::time else s.start_time end;
      n_dur    := case when v_chg ? 'duration_min' then nullif(v_chg->>'duration_min', '')::integer else s.duration_min end;
      n_aud    := case when v_chg ? 'audience'     then v_chg->>'audience' else s.audience end;
      n_plan   := case when v_chg ? 'plan_id'      then nullif(v_chg->>'plan_id', '')::uuid else s.plan_id end;
      n_counts := case when v_chg ? 'counts_toward_attendance' then (v_chg->>'counts_toward_attendance')::boolean else s.counts_toward_attendance end;
      n_meet   := case when v_chg ? 'is_meeting'   then (v_chg->>'is_meeting')::boolean else s.is_meeting end;
      n_off    := case when v_chg ? 'is_offsite'   then (v_chg->>'is_offsite')::boolean else s.is_offsite end;
      n_label  := case when v_chg ? 'location_label' then nullif(btrim(v_chg->>'location_label'), '') else s.location_label end;
      n_astart := case when v_chg ? 'actual_start' then nullif(v_chg->>'actual_start', '')::time else s.actual_start end;
      n_aend   := case when v_chg ? 'actual_end'   then nullif(v_chg->>'actual_end', '')::time else s.actual_end end;
      n_setup  := case when v_chg ? 'setup_min'    then nullif(v_chg->>'setup_min', '')::integer else s.setup_min end;
      if n_title is null or n_title = '' then raise exception 'BAD_VALUE: a session needs a title.'; end if;
      if n_date is null then raise exception 'BAD_VALUE: a session needs a date.'; end if;
      if n_counts is null or n_off is null then raise exception 'BAD_VALUE: counts_toward_attendance / is_offsite cannot be blank.'; end if;
      if n_dur is not null and (n_dur < 1 or n_dur > 1440) then raise exception 'BAD_VALUE: a length is 1–1440 minutes.'; end if;
      if (n_astart is null) <> (n_aend is null) then raise exception 'BAD_VALUE: the actual start and end go together — give both or clear both.'; end if;
      if n_astart is not null then
        if n_aend = n_astart then raise exception 'BAD_VALUE: the actual end must differ from the start.'; end if;
        if extract(second from n_astart) <> 0 or extract(second from n_aend) <> 0 then raise exception 'BAD_VALUE: actual times are whole minutes.'; end if;
        v_span := ((extract(epoch from (n_aend - n_astart)) / 60)::integer + case when n_aend <= n_astart then 1440 else 0 end);   -- an end at or before the start ran past midnight
        if v_chg ? 'duration_min' and n_dur is distinct from v_span then
          raise exception 'BAD_VALUE: the length comes from the actual start and end (% minutes) — change the times instead.', v_span;
        end if;
        n_dur := v_span;
      end if;
      if n_setup is not null and (n_setup < 0 or n_setup > 600) then raise exception 'BAD_VALUE: setup is 0–600 minutes.'; end if;
      if n_aud is null or n_aud not in ('everyone', 'leadership', 'board') then raise exception 'BAD_VALUE: unknown audience.'; end if;
      if n_plan is distinct from s.plan_id and n_plan is not null
         and not exists (select 1 from public.training_plans tp where tp.id = n_plan and tp.department_id = v_dept) then
        raise exception 'BAD_VALUE: that training category is not in your department.';
      end if;
      if n_aud <> 'everyone' then n_meet := false; end if;      -- only an everyone session carries the meeting flag (client rule)
      if not n_off then n_label := null; end if;                -- off -> no label / coordinates (coords CHECK)

      -- C1 hybrid (D2: the earlier of the current and corrected date)
      if least(s."date", n_date) < v_today - 14
         and not exists (select 1 from public.members m where m.id = v_me and m.department_id = v_dept
                           and m.status in ('Active', 'Probationary') and m.access && array['Department Admin']::text[]) then
        raise exception 'DA_ONLY: correcting a drill more than 14 days old is for a Department Admin.' using errcode = '42501';
      end if;

      -- old -> new, only what actually changes
      if n_title  is distinct from s.title        then v_diff := v_diff || jsonb_build_object('title',        jsonb_build_object('old', s.title, 'new', n_title)); end if;
      if n_date   is distinct from s."date"       then v_diff := v_diff || jsonb_build_object('date',         jsonb_build_object('old', s."date", 'new', n_date)); end if;
      if n_start  is distinct from s.start_time   then v_diff := v_diff || jsonb_build_object('start_time',   jsonb_build_object('old', s.start_time, 'new', n_start)); end if;
      if n_dur    is distinct from s.duration_min then v_diff := v_diff || jsonb_build_object('duration_min', jsonb_build_object('old', s.duration_min, 'new', n_dur)); end if;
      if n_astart is distinct from s.actual_start then v_diff := v_diff || jsonb_build_object('actual_start', jsonb_build_object('old', s.actual_start, 'new', n_astart)); end if;
      if n_aend   is distinct from s.actual_end   then v_diff := v_diff || jsonb_build_object('actual_end',   jsonb_build_object('old', s.actual_end, 'new', n_aend)); end if;
      if n_setup  is distinct from s.setup_min    then v_diff := v_diff || jsonb_build_object('setup_min',    jsonb_build_object('old', s.setup_min, 'new', n_setup)); end if;
      if n_aud    is distinct from s.audience     then v_diff := v_diff || jsonb_build_object('audience',     jsonb_build_object('old', s.audience, 'new', n_aud)); end if;
      if n_plan   is distinct from s.plan_id      then v_diff := v_diff || jsonb_build_object('plan_id',      jsonb_build_object('old', s.plan_id, 'new', n_plan)); end if;
      if n_counts is distinct from s.counts_toward_attendance then v_diff := v_diff || jsonb_build_object('counts_toward_attendance', jsonb_build_object('old', s.counts_toward_attendance, 'new', n_counts)); end if;
      if n_meet   is distinct from s.is_meeting   then v_diff := v_diff || jsonb_build_object('is_meeting',   jsonb_build_object('old', s.is_meeting, 'new', n_meet)); end if;
      if n_off    is distinct from s.is_offsite   then v_diff := v_diff || jsonb_build_object('is_offsite',   jsonb_build_object('old', s.is_offsite, 'new', n_off)); end if;
      if n_label  is distinct from s.location_label then v_diff := v_diff || jsonb_build_object('location_label', jsonb_build_object('old', s.location_label, 'new', n_label)); end if;
      if not n_off and (s.location_lat is not null or s.location_lng is not null) then
        v_diff := v_diff || jsonb_build_object('location', jsonb_build_object('old', jsonb_build_object('lat', s.location_lat, 'lng', s.location_lng, 'radius_m', s.location_radius_m), 'new', null));
      end if;

      -- roster deltas: deduped, disjoint, truthful (no "adding" someone already there, no "removing" someone absent)
      select coalesce(array_agg(distinct x order by x), '{}') into v_add from unnest(coalesce(p_add, '{}')) x where x is not null;
      select coalesce(array_agg(distinct x order by x), '{}') into v_rem from unnest(coalesce(p_remove, '{}')) x where x is not null;
      if v_add && v_rem then raise exception 'BAD_ROSTER: a member cannot be both added and removed.'; end if;
      if exists (select 1 from unnest(v_add) x where not exists (select 1 from public.members m where m.id = x and m.department_id = v_dept)) then
        raise exception 'BAD_ROSTER: someone being added is not a member of your department.';
      end if;
      if exists (select 1 from unnest(v_add) x where exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = x)) then
        raise exception 'BAD_ROSTER: someone being added is already on the roll.';
      end if;
      if exists (select 1 from unnest(v_rem) x where not exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = x)) then
        raise exception 'BAD_ROSTER: someone being removed is not on the roll.';
      end if;
      if v_diff = '{}'::jsonb and cardinality(v_add) = 0 and cardinality(v_rem) = 0 then
        raise exception 'NO_CHANGE: nothing to correct.';
      end if;

      select count(*) into v_before from public.session_attendance where session_id = s.id;
      perform set_config('b4c.session_correction', 'on', true);
      -- removals BEFORE the date moves (someone leaving the roll must not block a date their window excludes);
      -- additions AFTER (their window is checked against the corrected date)
      delete from public.session_attendance where session_id = s.id and member_id = any (v_rem);
      if v_diff <> '{}'::jsonb then
        update public.training_sessions
           set title = n_title, "date" = n_date, start_time = n_start, duration_min = n_dur, audience = n_aud, plan_id = n_plan,
               actual_start = n_astart, actual_end = n_aend, setup_min = n_setup,
               counts_toward_attendance = n_counts, is_meeting = n_meet, is_offsite = n_off, location_label = n_label,
               location_lat = case when n_off then location_lat end,
               location_lng = case when n_off then location_lng end,
               location_radius_m = case when n_off then location_radius_m end
         where id = s.id;
      end if;
      insert into public.session_attendance (department_id, session_id, member_id, checked_in_at)
      select v_dept, s.id, x, now() from unnest(v_add) x;
      perform set_config('b4c.session_correction', '', true);
      select count(*) into v_after from public.session_attendance where session_id = s.id;

      perform public.recompute_training_plan_last_iso(s.plan_id);
      if n_plan is distinct from s.plan_id then perform public.recompute_training_plan_last_iso(n_plan); end if;

      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_added, roster_removed, roster_before, roster_after)
      values (v_dept, s.id, 'correct', v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
              v_reason, v_diff, v_add, v_rem, v_before, v_after)
      returning id into v_audit;
      return jsonb_build_object('audit_id', v_audit, 'changes', v_diff, 'roster_added', to_jsonb(v_add),
                                'roster_removed', to_jsonb(v_rem), 'roster_before', v_before, 'roster_after', v_after);
    end;
    $function$
;

  -- ---------------------------------------------------------------- 4. the NEW times finalize (the length-only overload is untouched — the fallback)
CREATE FUNCTION public.finalize_training_session(p_session_id uuid, p_actual_start time without time zone, p_actual_end time without time zone, p_setup_min integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    -- B4C:E1E3 slice T — FINALIZE WITH THE ACTUAL TIMES (the length-only finalize_training_session(uuid, integer) stays as the
    -- fallback). The length is DERIVED from the actual start/end (an end at or before the start ran past midnight); setup_min
    -- is recorded only, never credited. NO DEFAULTS, on purpose: PostgREST picks an overload by its set of argument names, so
    -- this one answers ONLY {p_session_id, p_actual_start, p_actual_end, p_setup_min} and the length-only one ONLY
    -- {p_session_id, p_duration_min} — no call shape can match both (the clients that send p_duration_min keep the old
    -- function until they're updated). Otherwise exactly slice 6 C4: done, plus a FIRST length, logged. R4: a category's
    -- last_iso becomes greatest(existing, the drill's date) — and only when the roll is non-empty. If the session was
    -- reopened, the roster change since that Reopen is logged here (D4).
    declare
      v_dept  uuid := public.my_department_id();
      v_me    uuid := public.my_member_id();
      s       public.training_sessions%rowtype;
      v_dur   integer;
      v_span  integer; v_setup integer;
      v_now   uuid[]; v_snap uuid[]; v_last text;
      v_add   uuid[] := '{}'; v_rem uuid[] := '{}';
      v_diff  jsonb := jsonb_build_object('done', jsonb_build_object('old', false, 'new', true));
      v_audit uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception 'Only a training officer or a Department Admin can finalize a session.' using errcode = '42501';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception 'NOT_FOUND: that session is not in your department.' using errcode = 'P0002'; end if;
      if s.done then raise exception 'ALREADY_FINALIZED: this session is already finalized.'; end if;
      -- B4C:slice7 — a cancelled drill didn't happen: nothing to finalize.
      if s.status = 'cancelled' then raise exception 'CANCELLED: this session was cancelled — restore it before finalizing.'; end if;
      if s.signin_open then raise exception 'SIGNIN_OPEN: close the QR sign-in first.'; end if;
      if p_actual_start is null or p_actual_end is null then
        raise exception 'BAD_VALUE: give both the actual start and end — or finalize with just a length.';
      end if;
      if p_actual_end = p_actual_start then raise exception 'BAD_VALUE: the actual end must differ from the start.'; end if;
      if extract(second from p_actual_start) <> 0 or extract(second from p_actual_end) <> 0 then raise exception 'BAD_VALUE: actual times are whole minutes.'; end if;
      if p_setup_min is not null and (p_setup_min < 0 or p_setup_min > 600) then raise exception 'BAD_VALUE: setup is 0–600 minutes.'; end if;
      v_span := ((extract(epoch from (p_actual_end - p_actual_start)) / 60)::integer + case when p_actual_end <= p_actual_start then 1440 else 0 end);   -- an end at or before the start ran past midnight
      if s.duration_min is not null and s.duration_min <> v_span then
        raise exception 'USE_CORRECT: this drill already has a length — change it with Correct.';
      end if;
      if s.actual_start is not null and (s.actual_start, s.actual_end) is distinct from (p_actual_start, p_actual_end) then
        raise exception 'USE_CORRECT: this drill already has actual times — change them with Correct.';
      end if;
      if s.setup_min is not null and p_setup_min is not null and s.setup_min <> p_setup_min then
        raise exception 'USE_CORRECT: this drill already has a setup time — change it with Correct.';
      end if;
      v_dur := v_span;
      v_setup := coalesce(s.setup_min, p_setup_min);
      if v_dur is distinct from s.duration_min then
        v_diff := v_diff || jsonb_build_object('duration_min', jsonb_build_object('old', s.duration_min, 'new', v_dur));
      end if;
      if p_actual_start is distinct from s.actual_start then v_diff := v_diff || jsonb_build_object('actual_start', jsonb_build_object('old', s.actual_start, 'new', p_actual_start)); end if;
      if p_actual_end is distinct from s.actual_end then v_diff := v_diff || jsonb_build_object('actual_end', jsonb_build_object('old', s.actual_end, 'new', p_actual_end)); end if;
      if v_setup is distinct from s.setup_min then v_diff := v_diff || jsonb_build_object('setup_min', jsonb_build_object('old', s.setup_min, 'new', v_setup)); end if;
      select coalesce(array_agg(sa.member_id order by sa.member_id), '{}') into v_now
        from public.session_attendance sa where sa.session_id = s.id;
      -- the latest log entry for this session: if it is a Reopen, compare the roll now with the roll then
      select a.action, a.roster_snapshot into v_last, v_snap
        from public.training_session_audit a where a.session_id = s.id order by a.seq desc limit 1;
      if v_last = 'reopen' then
        select coalesce(array_agg(x order by x), '{}') into v_add from unnest(v_now) x where x <> all (coalesce(v_snap, '{}'));
        select coalesce(array_agg(x order by x), '{}') into v_rem from unnest(coalesce(v_snap, '{}')) x where x <> all (v_now);
      end if;
      update public.training_sessions set done = true, duration_min = v_dur, actual_start = p_actual_start, actual_end = p_actual_end, setup_min = v_setup where id = s.id;
      if s.plan_id is not null and cardinality(v_now) > 0 then
        update public.training_plans set last_iso = greatest(coalesce(last_iso, s."date"), s."date") where id = s.plan_id;
      end if;
      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_added, roster_removed, roster_before, roster_after)
      values (v_dept, s.id, 'finalize', v_me, coalesce((select m.name from public.members m where m.id = v_me), 'Unknown'),
              null, v_diff, v_add, v_rem,
              cardinality(v_now) - cardinality(v_add) + cardinality(v_rem), cardinality(v_now))
      returning id into v_audit;
      return jsonb_build_object('audit_id', v_audit, 'present', cardinality(v_now), 'duration_min', v_dur, 'actual_start', p_actual_start, 'actual_end', p_actual_end, 'setup_min', v_setup,
                                'roster_added', to_jsonb(v_add), 'roster_removed', to_jsonb(v_rem));
    end;
    $function$
;
  REVOKE ALL ON FUNCTION public.finalize_training_session(uuid, time without time zone, time without time zone, integer) FROM PUBLIC, anon;
  GRANT EXECUTE ON FUNCTION public.finalize_training_session(uuid, time without time zone, time without time zone, integer) TO authenticated, service_role;

  -- ---------------------------------------------------------------- 5. post-conditions (in-transaction)

    v_led_after := '{}'::jsonb;
    FOR d IN SELECT id FROM public.departments ORDER BY id LOOP
      v_led_after := v_led_after || jsonb_build_object(d::text, jsonb_build_object(
        'attested', (SELECT md5(coalesce(string_agg(a.member_id || '|' || a.session_id || '|' || a.start_at || '|' || a.end_at || '|' || a.optional, ',' ORDER BY a.member_id, a.session_id), ''))
                       FROM public.attested_training(d, '1900-01-01'::timestamptz, '2200-01-01'::timestamptz) a),
        'iso', (SELECT md5(coalesce(string_agg(h.member_id || '|' || h.training_hours || '|' || h.standby_hours || '|' || h.iso_total_hours, ',' ORDER BY h.member_id), ''))
                  FROM public.dept_iso_hours_for(d, '1900-01-01'::timestamptz, '2200-01-01'::timestamptz) h)));
    END LOOP;
  IF v_led_after IS DISTINCT FROM v_led_before THEN
    SELECT string_agg(k, ', ') INTO v_t FROM jsonb_object_keys(v_led_before) k WHERE (v_led_before->k) IS DISTINCT FROM (v_led_after->k);
    RAISE EXCEPTION 'Post-condition failed: the credited-hours ledger moved for department(s) %. Rolling back.', v_t;
  END IF;
  IF (SELECT md5(coalesce(string_agg((to_jsonb(ts) - 'actual_start' - 'actual_end' - 'setup_min')::text, ',' ORDER BY ts.id), '')) FROM public.training_sessions ts) IS DISTINCT FROM v_rows THEN RAISE EXCEPTION 'Post-condition failed: a training_sessions row changed. Rolling back.'; END IF;
  IF EXISTS (SELECT 1 FROM public.training_sessions WHERE actual_start IS NOT NULL OR actual_end IS NOT NULL OR setup_min IS NOT NULL) THEN
    RAISE EXCEPTION 'Post-condition failed: a new column is not NULL on an existing row. Rolling back.';
  END IF;
  IF (SELECT string_agg(column_name || ':' || udt_name || ':' || is_nullable, ',' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'training_sessions') IS DISTINCT FROM 'id:uuid:NO,department_id:uuid:NO,plan_id:uuid:YES,title:text:NO,date:date:NO,done:bool:NO,created_at:timestamptz:NO,signin_token:text:YES,signin_open:bool:NO,series_id:uuid:YES,audience:text:NO,start_time:time:YES,counts_toward_attendance:bool:NO,location_lat:float8:YES,location_lng:float8:YES,location_radius_m:int4:YES,location_label:text:YES,is_offsite:bool:NO,duration_min:int2:YES,is_meeting:bool:NO,status:text:NO,actual_start:time:YES,actual_end:time:YES,setup_min:int2:YES' THEN RAISE EXCEPTION 'Post-condition failed: the training_sessions columns are not as intended. Rolling back.'; END IF;
  IF (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public.training_sessions'::regclass AND conname IN ('training_sessions_actual_pair', 'training_sessions_actual_whole_minutes', 'training_sessions_actual_length', 'training_sessions_setup_range') AND convalidated) <> 4 THEN
    RAISE EXCEPTION 'Post-condition failed: the four slice-T CHECKs are not all present and validated. Rolling back.';
  END IF;
  IF (SELECT md5(string_agg(conname || '|' || pg_get_constraintdef(oid), ',' ORDER BY conname COLLATE "C")) FROM pg_constraint WHERE conrelid = 'public.training_sessions'::regclass AND contype <> 'n' AND conname NOT LIKE 'training_sessions\_actual\_%' AND conname <> 'training_sessions_setup_range') IS DISTINCT FROM '56d93bbf68ed673369ecc7f1f9b0f981' THEN RAISE EXCEPTION 'Post-condition failed: a pre-existing constraint changed. Rolling back.'; END IF;
  -- the bodies are exactly the generated text; ACLs as intended
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'public.tg_training_session_lock_guard()'::regprocedure) IS DISTINCT FROM '
    -- B4C:slice6 C7 — once a session is FINALIZED or HAS ATTENDANCE (Slice 7: or is CANCELLED), the fields that define the
    -- record (and the attested hours derived from it) change only through the RPCs, which set the transaction-local flag.
    -- Exempt so Finalize / sign-in keep working: done, signin_open, signin_token, location_lat/lng/radius_m,
    -- location_label, and duration_min NULL -> a value on a not-yet-finalized row (Finalize''s length prompt).
    -- Slice 7: status (''scheduled''/''cancelled'') changes ONLY under the flag (approve_session_change), on any row, and a new
    -- row is always ''scheduled''. date / start_time stay free on an upcoming, unattended session (plain Edit — ruling 3b).
    -- Applies to EVERY writer, the table owner included — a hand fix in the SQL editor must set the flag on purpose.
    -- B4C:E1E3 slice T — actual_start / actual_end / setup_min follow duration_min''s rule: set once on a not-yet-finalized row
    -- (Finalize), Correct-only after.
    begin
      if coalesce(current_setting(''b4c.session_correction'', true), '''') = ''on'' then return NEW; end if;
      if TG_OP = ''INSERT'' then
        if NEW.status is distinct from ''scheduled'' then
          raise exception ''STATUS_LOCKED: a session is created scheduled — cancelling takes the two-person sign-off.'' using errcode = ''42501'';
        end if;
        return NEW;
      end if;
      if NEW.status is distinct from OLD.status then
        raise exception ''STATUS_LOCKED: a session is cancelled or restored only through the two-person sign-off.'' using errcode = ''42501'';
      end if;
      if not (OLD.done is true or OLD.status = ''cancelled'' or exists (select 1 from public.session_attendance sa where sa.session_id = OLD.id)) then
        return NEW;
      end if;
      if NEW.title is distinct from OLD.title
         or NEW."date" is distinct from OLD."date"
         or NEW.start_time is distinct from OLD.start_time
         or NEW.audience is distinct from OLD.audience
         or NEW.plan_id is distinct from OLD.plan_id
         or NEW.counts_toward_attendance is distinct from OLD.counts_toward_attendance
         or NEW.is_meeting is distinct from OLD.is_meeting
         or NEW.is_offsite is distinct from OLD.is_offsite
         or NEW.department_id is distinct from OLD.department_id
         or NEW.series_id is distinct from OLD.series_id
         or (NEW.duration_min is distinct from OLD.duration_min
             and not (OLD.duration_min is null and OLD.done is not true))
         or (NEW.actual_start is distinct from OLD.actual_start
             and not (OLD.actual_start is null and OLD.done is not true))
         or (NEW.actual_end is distinct from OLD.actual_end
             and not (OLD.actual_end is null and OLD.done is not true))
         or (NEW.setup_min is distinct from OLD.setup_min
             and not (OLD.setup_min is null and OLD.done is not true)) then
        raise exception ''LOCKED_SESSION: this session is finalized, cancelled or has attendance — change it with Correct (or Restore), which is logged.''
          using errcode = ''42501'';
      end if;
      return NEW;
    end;
    ' OR coalesce((SELECT proacl::text FROM pg_proc WHERE oid = 'public.tg_training_session_lock_guard()'::regprocedure), '') IS DISTINCT FROM '{postgres=X/postgres,service_role=X/postgres}' THEN
    RAISE EXCEPTION 'Post-condition failed: the lock guard is not the generated body, or its ACL changed. Rolling back.';
  END IF;
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'public.correct_training_session(uuid, jsonb, uuid[], uuid[], text)'::regprocedure) IS DISTINCT FROM '
    -- B4C:slice6 — the gated, logged correction of a LOCKED session (finalized, sign-in open, or anyone on the roll).
    -- C1 hybrid: a training manager within 14 days of the drill (Central); older = Department Admin only (D1: the ROLE,
    -- never Project Admin). C2: a reason of 10+ characters. Fields: §2a whitelist only. Roster: add/remove in the same
    -- transaction; the membership-window triggers still run, and a refusal there aborts the whole call (nothing written).
    -- B4C:E1E3 slice T — actual_start / actual_end / setup_min are correctable. With times present the length is DERIVED from
    -- them (the CHECK enforces it); a duration_min that disagrees is refused. Clearing both times leaves a length-only session.
    declare
      v_dept   uuid := public.my_department_id();
      v_me     uuid := public.my_member_id();
      v_today  date := (now() at time zone ''America/Chicago'')::date;
      v_reason text := btrim(coalesce(p_reason, ''''));
      v_chg    jsonb := coalesce(p_changes, ''{}''::jsonb);
      v_keys   constant text[] := array[''title'', ''date'', ''start_time'', ''duration_min'', ''audience'', ''plan_id'',
                                        ''counts_toward_attendance'', ''is_meeting'', ''is_offsite'', ''location_label'',
                                        ''actual_start'', ''actual_end'', ''setup_min''];
      s        public.training_sessions%rowtype;
      v_bad    text[];
      n_title text; n_date date; n_start time; n_dur integer; n_aud text; n_plan uuid;
      n_counts boolean; n_meet boolean; n_off boolean; n_label text;
      n_astart time; n_aend time; n_setup integer; v_span integer;
      v_diff   jsonb := ''{}''::jsonb;
      v_add    uuid[]; v_rem uuid[];
      v_before integer; v_after integer;
      v_audit  uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception ''Only a training officer or a Department Admin can correct a session.'' using errcode = ''42501'';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception ''NOT_FOUND: that session is not in your department.'' using errcode = ''P0002''; end if;
      -- B4C:slice7 — a cancelled session is restored (two-person), not corrected.
      if s.status = ''cancelled'' then raise exception ''CANCELLED: this session was cancelled — restore it before correcting it.''; end if;
      if not (s.done or s.signin_open or exists (select 1 from public.session_attendance sa where sa.session_id = s.id)) then
        raise exception ''NOT_LOCKED: this session can still be edited normally — no correction needed.'';
      end if;
      if length(v_reason) < 10 then raise exception ''REASON_REQUIRED: say why (at least 10 characters).''; end if;
      if jsonb_typeof(v_chg) <> ''object'' then raise exception ''BAD_CHANGES: changes must be a JSON object.''; end if;
      select array_agg(k order by k) into v_bad from jsonb_object_keys(v_chg) k where k <> all (v_keys);
      if v_bad is not null then raise exception ''UNKNOWN_FIELD: % cannot be corrected here.'', array_to_string(v_bad, '', ''); end if;

      -- the corrected values (an absent key = unchanged)
      n_title  := case when v_chg ? ''title''        then btrim(v_chg->>''title'') else s.title end;
      n_date   := case when v_chg ? ''date''         then (v_chg->>''date'')::date else s."date" end;
      n_start  := case when v_chg ? ''start_time''   then nullif(v_chg->>''start_time'', '''')::time else s.start_time end;
      n_dur    := case when v_chg ? ''duration_min'' then nullif(v_chg->>''duration_min'', '''')::integer else s.duration_min end;
      n_aud    := case when v_chg ? ''audience''     then v_chg->>''audience'' else s.audience end;
      n_plan   := case when v_chg ? ''plan_id''      then nullif(v_chg->>''plan_id'', '''')::uuid else s.plan_id end;
      n_counts := case when v_chg ? ''counts_toward_attendance'' then (v_chg->>''counts_toward_attendance'')::boolean else s.counts_toward_attendance end;
      n_meet   := case when v_chg ? ''is_meeting''   then (v_chg->>''is_meeting'')::boolean else s.is_meeting end;
      n_off    := case when v_chg ? ''is_offsite''   then (v_chg->>''is_offsite'')::boolean else s.is_offsite end;
      n_label  := case when v_chg ? ''location_label'' then nullif(btrim(v_chg->>''location_label''), '''') else s.location_label end;
      n_astart := case when v_chg ? ''actual_start'' then nullif(v_chg->>''actual_start'', '''')::time else s.actual_start end;
      n_aend   := case when v_chg ? ''actual_end''   then nullif(v_chg->>''actual_end'', '''')::time else s.actual_end end;
      n_setup  := case when v_chg ? ''setup_min''    then nullif(v_chg->>''setup_min'', '''')::integer else s.setup_min end;
      if n_title is null or n_title = '''' then raise exception ''BAD_VALUE: a session needs a title.''; end if;
      if n_date is null then raise exception ''BAD_VALUE: a session needs a date.''; end if;
      if n_counts is null or n_off is null then raise exception ''BAD_VALUE: counts_toward_attendance / is_offsite cannot be blank.''; end if;
      if n_dur is not null and (n_dur < 1 or n_dur > 1440) then raise exception ''BAD_VALUE: a length is 1–1440 minutes.''; end if;
      if (n_astart is null) <> (n_aend is null) then raise exception ''BAD_VALUE: the actual start and end go together — give both or clear both.''; end if;
      if n_astart is not null then
        if n_aend = n_astart then raise exception ''BAD_VALUE: the actual end must differ from the start.''; end if;
        if extract(second from n_astart) <> 0 or extract(second from n_aend) <> 0 then raise exception ''BAD_VALUE: actual times are whole minutes.''; end if;
        v_span := ((extract(epoch from (n_aend - n_astart)) / 60)::integer + case when n_aend <= n_astart then 1440 else 0 end);   -- an end at or before the start ran past midnight
        if v_chg ? ''duration_min'' and n_dur is distinct from v_span then
          raise exception ''BAD_VALUE: the length comes from the actual start and end (% minutes) — change the times instead.'', v_span;
        end if;
        n_dur := v_span;
      end if;
      if n_setup is not null and (n_setup < 0 or n_setup > 600) then raise exception ''BAD_VALUE: setup is 0–600 minutes.''; end if;
      if n_aud is null or n_aud not in (''everyone'', ''leadership'', ''board'') then raise exception ''BAD_VALUE: unknown audience.''; end if;
      if n_plan is distinct from s.plan_id and n_plan is not null
         and not exists (select 1 from public.training_plans tp where tp.id = n_plan and tp.department_id = v_dept) then
        raise exception ''BAD_VALUE: that training category is not in your department.'';
      end if;
      if n_aud <> ''everyone'' then n_meet := false; end if;      -- only an everyone session carries the meeting flag (client rule)
      if not n_off then n_label := null; end if;                -- off -> no label / coordinates (coords CHECK)

      -- C1 hybrid (D2: the earlier of the current and corrected date)
      if least(s."date", n_date) < v_today - 14
         and not exists (select 1 from public.members m where m.id = v_me and m.department_id = v_dept
                           and m.status in (''Active'', ''Probationary'') and m.access && array[''Department Admin'']::text[]) then
        raise exception ''DA_ONLY: correcting a drill more than 14 days old is for a Department Admin.'' using errcode = ''42501'';
      end if;

      -- old -> new, only what actually changes
      if n_title  is distinct from s.title        then v_diff := v_diff || jsonb_build_object(''title'',        jsonb_build_object(''old'', s.title, ''new'', n_title)); end if;
      if n_date   is distinct from s."date"       then v_diff := v_diff || jsonb_build_object(''date'',         jsonb_build_object(''old'', s."date", ''new'', n_date)); end if;
      if n_start  is distinct from s.start_time   then v_diff := v_diff || jsonb_build_object(''start_time'',   jsonb_build_object(''old'', s.start_time, ''new'', n_start)); end if;
      if n_dur    is distinct from s.duration_min then v_diff := v_diff || jsonb_build_object(''duration_min'', jsonb_build_object(''old'', s.duration_min, ''new'', n_dur)); end if;
      if n_astart is distinct from s.actual_start then v_diff := v_diff || jsonb_build_object(''actual_start'', jsonb_build_object(''old'', s.actual_start, ''new'', n_astart)); end if;
      if n_aend   is distinct from s.actual_end   then v_diff := v_diff || jsonb_build_object(''actual_end'',   jsonb_build_object(''old'', s.actual_end, ''new'', n_aend)); end if;
      if n_setup  is distinct from s.setup_min    then v_diff := v_diff || jsonb_build_object(''setup_min'',    jsonb_build_object(''old'', s.setup_min, ''new'', n_setup)); end if;
      if n_aud    is distinct from s.audience     then v_diff := v_diff || jsonb_build_object(''audience'',     jsonb_build_object(''old'', s.audience, ''new'', n_aud)); end if;
      if n_plan   is distinct from s.plan_id      then v_diff := v_diff || jsonb_build_object(''plan_id'',      jsonb_build_object(''old'', s.plan_id, ''new'', n_plan)); end if;
      if n_counts is distinct from s.counts_toward_attendance then v_diff := v_diff || jsonb_build_object(''counts_toward_attendance'', jsonb_build_object(''old'', s.counts_toward_attendance, ''new'', n_counts)); end if;
      if n_meet   is distinct from s.is_meeting   then v_diff := v_diff || jsonb_build_object(''is_meeting'',   jsonb_build_object(''old'', s.is_meeting, ''new'', n_meet)); end if;
      if n_off    is distinct from s.is_offsite   then v_diff := v_diff || jsonb_build_object(''is_offsite'',   jsonb_build_object(''old'', s.is_offsite, ''new'', n_off)); end if;
      if n_label  is distinct from s.location_label then v_diff := v_diff || jsonb_build_object(''location_label'', jsonb_build_object(''old'', s.location_label, ''new'', n_label)); end if;
      if not n_off and (s.location_lat is not null or s.location_lng is not null) then
        v_diff := v_diff || jsonb_build_object(''location'', jsonb_build_object(''old'', jsonb_build_object(''lat'', s.location_lat, ''lng'', s.location_lng, ''radius_m'', s.location_radius_m), ''new'', null));
      end if;

      -- roster deltas: deduped, disjoint, truthful (no "adding" someone already there, no "removing" someone absent)
      select coalesce(array_agg(distinct x order by x), ''{}'') into v_add from unnest(coalesce(p_add, ''{}'')) x where x is not null;
      select coalesce(array_agg(distinct x order by x), ''{}'') into v_rem from unnest(coalesce(p_remove, ''{}'')) x where x is not null;
      if v_add && v_rem then raise exception ''BAD_ROSTER: a member cannot be both added and removed.''; end if;
      if exists (select 1 from unnest(v_add) x where not exists (select 1 from public.members m where m.id = x and m.department_id = v_dept)) then
        raise exception ''BAD_ROSTER: someone being added is not a member of your department.'';
      end if;
      if exists (select 1 from unnest(v_add) x where exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = x)) then
        raise exception ''BAD_ROSTER: someone being added is already on the roll.'';
      end if;
      if exists (select 1 from unnest(v_rem) x where not exists (select 1 from public.session_attendance sa where sa.session_id = s.id and sa.member_id = x)) then
        raise exception ''BAD_ROSTER: someone being removed is not on the roll.'';
      end if;
      if v_diff = ''{}''::jsonb and cardinality(v_add) = 0 and cardinality(v_rem) = 0 then
        raise exception ''NO_CHANGE: nothing to correct.'';
      end if;

      select count(*) into v_before from public.session_attendance where session_id = s.id;
      perform set_config(''b4c.session_correction'', ''on'', true);
      -- removals BEFORE the date moves (someone leaving the roll must not block a date their window excludes);
      -- additions AFTER (their window is checked against the corrected date)
      delete from public.session_attendance where session_id = s.id and member_id = any (v_rem);
      if v_diff <> ''{}''::jsonb then
        update public.training_sessions
           set title = n_title, "date" = n_date, start_time = n_start, duration_min = n_dur, audience = n_aud, plan_id = n_plan,
               actual_start = n_astart, actual_end = n_aend, setup_min = n_setup,
               counts_toward_attendance = n_counts, is_meeting = n_meet, is_offsite = n_off, location_label = n_label,
               location_lat = case when n_off then location_lat end,
               location_lng = case when n_off then location_lng end,
               location_radius_m = case when n_off then location_radius_m end
         where id = s.id;
      end if;
      insert into public.session_attendance (department_id, session_id, member_id, checked_in_at)
      select v_dept, s.id, x, now() from unnest(v_add) x;
      perform set_config(''b4c.session_correction'', '''', true);
      select count(*) into v_after from public.session_attendance where session_id = s.id;

      perform public.recompute_training_plan_last_iso(s.plan_id);
      if n_plan is distinct from s.plan_id then perform public.recompute_training_plan_last_iso(n_plan); end if;

      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_added, roster_removed, roster_before, roster_after)
      values (v_dept, s.id, ''correct'', v_me, coalesce((select m.name from public.members m where m.id = v_me), ''Unknown''),
              v_reason, v_diff, v_add, v_rem, v_before, v_after)
      returning id into v_audit;
      return jsonb_build_object(''audit_id'', v_audit, ''changes'', v_diff, ''roster_added'', to_jsonb(v_add),
                                ''roster_removed'', to_jsonb(v_rem), ''roster_before'', v_before, ''roster_after'', v_after);
    end;
    ' OR coalesce((SELECT proacl::text FROM pg_proc WHERE oid = 'public.correct_training_session(uuid, jsonb, uuid[], uuid[], text)'::regprocedure), '') IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN
    RAISE EXCEPTION 'Post-condition failed: correct_training_session is not the generated body, or its ACL changed. Rolling back.';
  END IF;
  IF (SELECT prosrc FROM pg_proc WHERE oid = 'public.finalize_training_session(uuid, time without time zone, time without time zone, integer)'::regprocedure) IS DISTINCT FROM '
    -- B4C:E1E3 slice T — FINALIZE WITH THE ACTUAL TIMES (the length-only finalize_training_session(uuid, integer) stays as the
    -- fallback). The length is DERIVED from the actual start/end (an end at or before the start ran past midnight); setup_min
    -- is recorded only, never credited. NO DEFAULTS, on purpose: PostgREST picks an overload by its set of argument names, so
    -- this one answers ONLY {p_session_id, p_actual_start, p_actual_end, p_setup_min} and the length-only one ONLY
    -- {p_session_id, p_duration_min} — no call shape can match both (the clients that send p_duration_min keep the old
    -- function until they''re updated). Otherwise exactly slice 6 C4: done, plus a FIRST length, logged. R4: a category''s
    -- last_iso becomes greatest(existing, the drill''s date) — and only when the roll is non-empty. If the session was
    -- reopened, the roster change since that Reopen is logged here (D4).
    declare
      v_dept  uuid := public.my_department_id();
      v_me    uuid := public.my_member_id();
      s       public.training_sessions%rowtype;
      v_dur   integer;
      v_span  integer; v_setup integer;
      v_now   uuid[]; v_snap uuid[]; v_last text;
      v_add   uuid[] := ''{}''; v_rem uuid[] := ''{}'';
      v_diff  jsonb := jsonb_build_object(''done'', jsonb_build_object(''old'', false, ''new'', true));
      v_audit uuid;
    begin
      if v_dept is null or v_me is null or not coalesce(public.is_training_manager(), false) then
        raise exception ''Only a training officer or a Department Admin can finalize a session.'' using errcode = ''42501'';
      end if;
      select * into s from public.training_sessions where id = p_session_id and department_id = v_dept for update;
      if not found then raise exception ''NOT_FOUND: that session is not in your department.'' using errcode = ''P0002''; end if;
      if s.done then raise exception ''ALREADY_FINALIZED: this session is already finalized.''; end if;
      -- B4C:slice7 — a cancelled drill didn''t happen: nothing to finalize.
      if s.status = ''cancelled'' then raise exception ''CANCELLED: this session was cancelled — restore it before finalizing.''; end if;
      if s.signin_open then raise exception ''SIGNIN_OPEN: close the QR sign-in first.''; end if;
      if p_actual_start is null or p_actual_end is null then
        raise exception ''BAD_VALUE: give both the actual start and end — or finalize with just a length.'';
      end if;
      if p_actual_end = p_actual_start then raise exception ''BAD_VALUE: the actual end must differ from the start.''; end if;
      if extract(second from p_actual_start) <> 0 or extract(second from p_actual_end) <> 0 then raise exception ''BAD_VALUE: actual times are whole minutes.''; end if;
      if p_setup_min is not null and (p_setup_min < 0 or p_setup_min > 600) then raise exception ''BAD_VALUE: setup is 0–600 minutes.''; end if;
      v_span := ((extract(epoch from (p_actual_end - p_actual_start)) / 60)::integer + case when p_actual_end <= p_actual_start then 1440 else 0 end);   -- an end at or before the start ran past midnight
      if s.duration_min is not null and s.duration_min <> v_span then
        raise exception ''USE_CORRECT: this drill already has a length — change it with Correct.'';
      end if;
      if s.actual_start is not null and (s.actual_start, s.actual_end) is distinct from (p_actual_start, p_actual_end) then
        raise exception ''USE_CORRECT: this drill already has actual times — change them with Correct.'';
      end if;
      if s.setup_min is not null and p_setup_min is not null and s.setup_min <> p_setup_min then
        raise exception ''USE_CORRECT: this drill already has a setup time — change it with Correct.'';
      end if;
      v_dur := v_span;
      v_setup := coalesce(s.setup_min, p_setup_min);
      if v_dur is distinct from s.duration_min then
        v_diff := v_diff || jsonb_build_object(''duration_min'', jsonb_build_object(''old'', s.duration_min, ''new'', v_dur));
      end if;
      if p_actual_start is distinct from s.actual_start then v_diff := v_diff || jsonb_build_object(''actual_start'', jsonb_build_object(''old'', s.actual_start, ''new'', p_actual_start)); end if;
      if p_actual_end is distinct from s.actual_end then v_diff := v_diff || jsonb_build_object(''actual_end'', jsonb_build_object(''old'', s.actual_end, ''new'', p_actual_end)); end if;
      if v_setup is distinct from s.setup_min then v_diff := v_diff || jsonb_build_object(''setup_min'', jsonb_build_object(''old'', s.setup_min, ''new'', v_setup)); end if;
      select coalesce(array_agg(sa.member_id order by sa.member_id), ''{}'') into v_now
        from public.session_attendance sa where sa.session_id = s.id;
      -- the latest log entry for this session: if it is a Reopen, compare the roll now with the roll then
      select a.action, a.roster_snapshot into v_last, v_snap
        from public.training_session_audit a where a.session_id = s.id order by a.seq desc limit 1;
      if v_last = ''reopen'' then
        select coalesce(array_agg(x order by x), ''{}'') into v_add from unnest(v_now) x where x <> all (coalesce(v_snap, ''{}''));
        select coalesce(array_agg(x order by x), ''{}'') into v_rem from unnest(coalesce(v_snap, ''{}'')) x where x <> all (v_now);
      end if;
      update public.training_sessions set done = true, duration_min = v_dur, actual_start = p_actual_start, actual_end = p_actual_end, setup_min = v_setup where id = s.id;
      if s.plan_id is not null and cardinality(v_now) > 0 then
        update public.training_plans set last_iso = greatest(coalesce(last_iso, s."date"), s."date") where id = s.plan_id;
      end if;
      insert into public.training_session_audit (department_id, session_id, action, actor_id, actor_name, reason, changes,
                                                 roster_added, roster_removed, roster_before, roster_after)
      values (v_dept, s.id, ''finalize'', v_me, coalesce((select m.name from public.members m where m.id = v_me), ''Unknown''),
              null, v_diff, v_add, v_rem,
              cardinality(v_now) - cardinality(v_add) + cardinality(v_rem), cardinality(v_now))
      returning id into v_audit;
      return jsonb_build_object(''audit_id'', v_audit, ''present'', cardinality(v_now), ''duration_min'', v_dur, ''actual_start'', p_actual_start, ''actual_end'', p_actual_end, ''setup_min'', v_setup,
                                ''roster_added'', to_jsonb(v_add), ''roster_removed'', to_jsonb(v_rem));
    end;
    '
     OR coalesce((SELECT proacl::text FROM pg_proc WHERE oid = 'public.finalize_training_session(uuid, time without time zone, time without time zone, integer)'::regprocedure), '') IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}'
     OR NOT (SELECT prosecdef FROM pg_proc WHERE oid = 'public.finalize_training_session(uuid, time without time zone, time without time zone, integer)'::regprocedure)
     OR has_function_privilege('anon', 'public.finalize_training_session(uuid, time without time zone, time without time zone, integer)', 'EXECUTE') THEN
    RAISE EXCEPTION 'Post-condition failed: the times finalize is not the generated body, not SECURITY DEFINER, or its ACL is wrong (anon must not execute). Rolling back.';
  END IF;
  -- the two finalize overloads: exactly these named-argument sets, NO defaults — no call shape (named, as PostgREST sends, or
  -- positional) can resolve to both, and the existing {p_session_id, p_duration_min} call keeps resolving to the old function
  IF (SELECT string_agg(array_to_string(p.proargnames, ',') || '/' || p.pronargdefaults, ' | ' ORDER BY p.pronargs)
        FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'finalize_training_session')
     IS DISTINCT FROM 'p_session_id,p_duration_min/0 | p_session_id,p_actual_start,p_actual_end,p_setup_min/0' THEN
    RAISE EXCEPTION 'Post-condition failed: the finalize overloads are not exactly {p_session_id,p_duration_min} and {p_session_id,p_actual_start,p_actual_end,p_setup_min} with no defaults. Rolling back.';
  END IF;
  -- setup_min / actual_* are read by exactly the three functions — nothing in the hours pipeline
  IF (SELECT array_agg(x ORDER BY x) FROM (SELECT unnest((SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text), '{}') FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prosrc ~ '(actual_start|actual_end|setup_min)')) EXCEPT SELECT unnest(v_readers)) z(x)) IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(ARRAY['correct_training_session(uuid,jsonb,uuid[],uuid[],text)', 'finalize_training_session(uuid,time without time zone,time without time zone,integer)', 'tg_training_session_lock_guard()']::text[]) x)
     OR NOT (v_readers <@ (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text), '{}') FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prosrc ~ '(actual_start|actual_end|setup_min)')) THEN
    RAISE EXCEPTION 'Post-condition failed: the functions reading the new columns are not exactly the three (finalize overload, correct, the guard). Rolling back.';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('v', 'm') AND pg_get_viewdef(c.oid) ~ '(actual_start|actual_end|setup_min)') THEN
    RAISE EXCEPTION 'Post-condition failed: a view reads a new column. Rolling back.';
  END IF;
  IF md5(pg_get_functiondef('public.attested_training(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)) IS DISTINCT FROM 'aff25333771cd38c1f473bcde5e1e96e' OR md5(pg_get_functiondef('public.dept_iso_hours_for(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)) IS DISTINCT FROM '705c9a9b5532d28824f5e50e74d6059f'
     OR md5(pg_get_functiondef('public.finalize_training_session(uuid, integer)'::regprocedure)) IS DISTINCT FROM '3f31142bae70c8fd2001c4fb657f4efa' THEN
    RAISE EXCEPTION 'Post-condition failed: attested_training / dept_iso_hours_for / the length-only finalize changed. Rolling back.';
  END IF;
  IF (SELECT md5(string_agg(md5(pg_get_functiondef(p.oid)) || coalesce(p.proacl::text, ''), ',' ORDER BY p.oid::regprocedure::text)) FROM pg_proc p
       WHERE p.pronamespace = 'public'::regnamespace AND p.prokind = 'f' AND p.oid::regprocedure::text NOT IN ('correct_training_session(uuid,jsonb,uuid[],uuid[],text)', 'tg_training_session_lock_guard()', 'finalize_training_session(uuid,time without time zone,time without time zone,integer)')) IS DISTINCT FROM v_others THEN RAISE EXCEPTION 'Post-condition failed: another public function changed. Rolling back.'; END IF;
  IF (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f') <> v_fn_n + 1 THEN
    RAISE EXCEPTION 'Post-condition failed: the function count is not +1. Rolling back.';
  END IF;
  IF (SELECT md5(string_agg(tablename || '|' || policyname || '|' || cmd || '|' || roles::text || '|' || coalesce(qual, '') || '|' || coalesce(with_check, ''), ',' ORDER BY tablename, policyname)) FROM pg_policies WHERE schemaname = 'public') IS DISTINCT FROM 'a9947383b4635e2e54fa89fa81947fc9' OR (SELECT md5(string_agg(t.tgname || '|' || pg_get_triggerdef(t.oid), ',' ORDER BY t.tgname COLLATE "C")) FROM pg_trigger t WHERE t.tgrelid = 'public.training_sessions'::regclass AND NOT t.tgisinternal) IS DISTINCT FROM 'de3d15eea057428cd6ece6612e7e8775' THEN
    RAISE EXCEPTION 'Post-condition failed: a policy or a training_sessions trigger changed. Rolling back.';
  END IF;
  IF (SELECT count(*) FROM public.station_presence WHERE verified) <> v_ver THEN RAISE EXCEPTION 'Post-condition failed: verified presence changed. Rolling back.'; END IF;
END
$migrate$;

NOTIFY pgrst, 'reload schema';

-- ---------------------------------------------------------------- state row
SELECT jsonb_build_object(
  'columns', (SELECT string_agg(column_name || ' ' || udt_name, ', ' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'training_sessions' AND column_name IN ('actual_start', 'actual_end', 'setup_min')),
  'checks', (SELECT jsonb_object_agg(conname, convalidated) FROM pg_constraint WHERE conrelid = 'public.training_sessions'::regclass AND conname IN ('training_sessions_actual_pair', 'training_sessions_actual_whole_minutes', 'training_sessions_actual_length', 'training_sessions_setup_range')),
  'finalize_overloads', (SELECT string_agg(p.oid::regprocedure::text, ' | ' ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'finalize_training_session'),
  'finalize_named_args', (SELECT string_agg(array_to_string(p.proargnames, ',') || ' (defaults ' || p.pronargdefaults || ')', ' | ' ORDER BY p.pronargs) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname = 'finalize_training_session'),
  'correct_md5', md5(pg_get_functiondef('public.correct_training_session(uuid, jsonb, uuid[], uuid[], text)'::regprocedure)), 'guard_md5', md5(pg_get_functiondef('public.tg_training_session_lock_guard()'::regprocedure)), 'times_finalize_md5', md5(pg_get_functiondef('public.finalize_training_session(uuid, time without time zone, time without time zone, integer)'::regprocedure)),
  'readers_of_new_columns', (SELECT coalesce(array_agg(p.oid::regprocedure::text ORDER BY p.oid::regprocedure::text), '{}') FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prosrc ~ '(actual_start|actual_end|setup_min)'),
  'attested_md5', md5(pg_get_functiondef('public.attested_training(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)), 'iso_md5', md5(pg_get_functiondef('public.dept_iso_hours_for(uuid, timestamp with time zone, timestamp with time zone)'::regprocedure)),
  'fn_count', (SELECT count(*) FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND prokind = 'f'),
  'total_policies', (SELECT count(*) FROM pg_policies WHERE schemaname = 'public'),
  'verified_presence', (SELECT count(*) FROM public.station_presence WHERE verified)
) AS state;
